import sys

def is_palindrome(s):
    if len(s) % 2 == 1 and all(s[i] != s[i+1] for i in range(len(s) - 1)):
        return True
    return s == s[::-1]

def longest_non_palindrome_substring(s):
    n = len(s)
    if n <= 1:
        return 0

    if not is_palindrome(s):
        return n

    if not is_palindrome(s[1:]) or not is_palindrome(s[:-1]):
        return n - 1

    return 0

input = sys.stdin.read
s = input().strip()
result = longest_non_palindrome_substring(s)
print(result)

